'use strict';
// Merge the device generated by the firmware dialog into local server config.
// Existing operator/cloud secrets, battery settings, calibration and anchors are preserved.
const fs = require('node:fs');
const path = require('node:path');
const root = __dirname;
const local = path.join(root, 'local');
const deviceFile = path.join(local, 'robot-device.private.json');
const robotFile = path.join(local, 'robot-private.json');
const trackerFile = path.join(local, 'tracker-private.json');
const read = file => JSON.parse(fs.readFileSync(file, 'utf8'));
function atomic(file, value) {
  const temp = file + '.' + process.pid + '.tmp';
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(temp, JSON.stringify(value, null, 2) + '\n', { mode: 0o600 });
  try { fs.renameSync(temp, file); }
  finally { if (fs.existsSync(temp)) fs.unlinkSync(temp); }
  try { fs.chmodSync(file, 0o600); } catch {}
}
function main() {
  if (!fs.existsSync(deviceFile)) throw Error('Missing local/robot-device.private.json. Extract the firmware ZIP again.');
  const device = read(deviceFile);
  if (!device || typeof device.id !== 'string' || !device.id || typeof device.token !== 'string' || device.token.length < 24)
    throw Error('Invalid device identity/token in local/robot-device.private.json.');

  const robotExample = path.join(local, 'robot-private.example.json');
  const config = fs.existsSync(robotFile) ? read(robotFile) : read(robotExample);
  if (!config.operatorToken || /^REPLACE_/.test(config.operatorToken))
    throw Error('Set a unique operatorToken in local/robot-private.json before syncing. Copy the example if needed.');
  if (!config.trackerToken || /^REPLACE_/.test(config.trackerToken))
    throw Error('Set a unique trackerToken in local/robot-private.json before syncing.');
  if (!Array.isArray(config.devices)) config.devices = [];
  config.devices = config.devices.filter(item => item && !/^REPLACE_/.test(String(item.id || '')));
  const template = read(robotExample).devices?.[0] || {};
  const index = config.devices.findIndex(item => item && item.id === device.id);
  const current = index >= 0 ? config.devices[index] : JSON.parse(JSON.stringify(template));
  Object.assign(current, device);
  if (index >= 0) config.devices[index] = current;
  else config.devices.push(current);

  const trackerExample = path.join(local, 'tracker-private.example.json');
  const tracker = fs.existsSync(trackerFile) ? read(trackerFile) : read(trackerExample);
  tracker.trackerToken = config.trackerToken;
  if (!Array.isArray(tracker.robots)) tracker.robots = [];
  tracker.robots = tracker.robots.filter(item => item && !/^REPLACE_/.test(String(item.id || '')));
  const oldIndex = tracker.robots.findIndex(item => item && item.id === device.id);
  const old = oldIndex >= 0 ? tracker.robots[oldIndex] : {};
  const trackingDevice = { ...old, id: device.id, polygon_id: device.polygon_id || null, marker_id: device.marker_id };
  if (oldIndex >= 0) tracker.robots[oldIndex] = trackingDevice;
  else tracker.robots.push(trackingDevice);

  atomic(robotFile, config);
  atomic(trackerFile, tracker);
  console.log('Device token synchronized with local/robot-private.json.');
  console.log('Tracker device list updated; existing anchors and calibration settings were preserved.');
}
try { main(); }
catch (error) { console.error('ROI device config:', error.message); process.exitCode = 1; }
